 75→		return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
 76→	}
 77→
 78→	provider = parts[0]
 79→	repo = parts[1]
 80→
 81→	switch provider {
 82→	case "github":
 83→		// valid
 84→	default:
 85→		return "", "", fmt.Errorf("unsupported provider %q (supported: github)", provider)
 86→	}
 87→
 88→	repoParts := strings.SplitN(repo, "/", 2)
 89→	if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
 90→		return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
